import{_ as r,o as t,c as a,a6 as i}from"./chunks/framework.DHIwV8r3.js";const m=JSON.parse('{"title":"Christophe Lemaire","description":"","frontmatter":{},"headers":[],"relativePath":"designers/christophe-lemaire.md","filePath":"designers/christophe-lemaire.md","lastUpdated":1794245099000}'),o={name:"designers/christophe-lemaire.md"};function s(n,e,h,l,p,d){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="christophe-lemaire" tabindex="-1">Christophe Lemaire <a class="header-anchor" href="#christophe-lemaire" aria-label="Permalink to &quot;Christophe Lemaire&quot;">​</a></h1><p><strong>Study for:</strong> everyday usefulness, proportion, and movement.</p><h2 id="brief-bio" tabindex="-1">Brief bio <a class="header-anchor" href="#brief-bio" aria-label="Permalink to &quot;Brief bio&quot;">​</a></h2><p>Christophe Lemaire is a French designer who founded his label in 1991 after working at Christian Lacroix and other Paris studios. He later led artistic direction at Lacoste and Hermès. Today, LEMAIRE’s creative work is shared with Sarah-Linh Tran; the house describes clothing designed for everyday life, with attention to movement, materials, and layering. <a href="https://www.lemaire.fr/pages/about-lemaire" target="_blank" rel="noreferrer">Official biography</a>.</p><p><strong><a href="https://www.lemaire.fr/pages/about-lemaire" target="_blank" rel="noreferrer">View the designers’ portraits</a></strong> — see the official page’s “Portraits” section. The photographs remain at their source; no reuse license has been verified here.</p><h2 id="apply-it-to-our-white-tee" tabindex="-1">Apply it to our white tee <a class="header-anchor" href="#apply-it-to-our-white-tee" aria-label="Permalink to &quot;Apply it to our white tee&quot;">​</a></h2><ul><li><strong>Product:</strong> test length and drape while sitting, reaching, and layering—not just standing for a photo.</li><li><strong>Website:</strong> show the same tee alone and under an overshirt, with useful fit notes.</li><li><strong>Brand:</strong> explain where the tee fits into a real week, rather than promising an abstract lifestyle.</li></ul><p>These are our proposed applications, not recommendations made by Lemaire or Tran.</p><p><strong>Try this:</strong> photograph a sample in three everyday situations. Ask which fit details would help someone choose a size online.</p><p><a href="/white-tee-research/our-brand.html">← Our brand</a> · <a href="./rei-kawakubo.html">Next: Rei Kawakubo</a></p><p><em>Sources reviewed November 9, 2026.</em></p>',11)])])}const f=r(o,[["render",s]]);export{m as __pageData,f as default};
